-- 既存のテーブルを削除して初期化
DROP TABLE IF EXISTS houses;
DROP TABLE IF EXISTS subsidies;

CREATE TABLE houses (
    id INTEGER PRIMARY KEY, transaction_type VARCHAR(20) NOT NULL, title VARCHAR(100) NOT NULL,
    prefecture VARCHAR(50) NOT NULL, municipality VARCHAR(50) NOT NULL, address TEXT,
    price INT, rent_monthly INT, layout VARCHAR(50), floors INT, land_area_m2 NUMERIC,
    building_area_m2 NUMERIC, tsubo NUMERIC, tsubo_unit_price_maruen NUMERIC,
    structure VARCHAR(50), built_year VARCHAR(50), renovation_cost_est INT, features TEXT,
    latitude NUMERIC, longitude NUMERIC
);
CREATE TABLE subsidies (
    id INT PRIMARY KEY, prefecture VARCHAR(50) NOT NULL, municipality VARCHAR(50),
    subsidy_name VARCHAR(100) NOT NULL, target_type VARCHAR(50), max_amount INT,
    rate VARCHAR(50), conditions TEXT
);
